    return '<div class="g2"><div class="card"><h3>' + ic('upload_file', 'pri') + ' Import Excel / CSV</h3><p class="sm mut" style="margin:4px 0 12px">Kolom: <b>NISN, Nama, Kelas</b>. Aman diulang (upsert berdasarkan NISN), ada pindai (dry-run) sebelum menulis. PIN murid baru = 4 digit terakhir NISN.</p><div class="drop" data-act="m.pick">' + ic('cloud_upload', 's40') + '<div>' + (S.file ? '<b>' + esc(S.file) + '</b> — ' + (S.rows || []).length + ' baris' : 'Klik untuk memilih berkas .xlsx / .xls / .csv') + '</div></div><input type="file" id="mfile" accept=".xlsx,.xls,.csv" class="hide" data-ch="m.file"><div class="row wrap" style="margin-top:12px"><button class="btn" data-act="m.tpl">' + ic('download', 's18') + 'Unduh templat</button><span class="grow"></span><button class="btn" data-act="m.scan"' + (S.rows ? '' : ' disabled') + '>Pindai (Dry-run)</button><button class="btn p" data-act="m.run"' + (S.rows && S.scanned ? '' : ' disabled') + '>Jalankan Import</button></div>' + res(S.imp) + '</div>' +
      '<div class="card"><h3>' + ic('sync_alt', 'pri') + ' Migrasi dari Spreadsheet Lain</h3><p class="sm mut" style="margin:4px 0 12px">Salin data murid dari spreadsheet lama (sheet <b>Murid</b>/<b>Siswa</b>). Sumber hanya <b>dibaca</b>, tidak diubah. Harus akun Google yang sama. Jalankan ulang kapan saja untuk sinkron delta.</p>' + H.fld('URL / ID spreadsheet sumber', '<input class="inp" id="mg-src" placeholder="https://docs.google.com/spreadsheets/d/…" value="' + esc(S.src || '') + '">') + '<div class="row" style="margin-top:12px"><span class="grow"></span><button class="btn" data-act="m.mig" data-d="1">Pindai (Dry-run)</button><button class="btn p" data-act="m.mig" data-d="0">Jalankan Migrasi</button></div>' + (S.mig ? '<div class="alert i" style="margin-top:12px">' + ic('info') + '<div><b>' + esc(S.mig.sumber) + '</b> — ' + (S.mig.dryRun ? 'hasil pindai' : 'selesai') + '<br>Sumber: ' + S.mig.report.Murid.sumber + ' baris • tambah ' + S.mig.report.Murid.inserted + ' • perbarui ' + S.mig.report.Murid.updated + ' • lewati ' + S.mig.report.Murid.skipped + '<br><span class="sm mut">' + S.mig.catatan.map(esc).join(' ') + '</span></div></div>' : '') + '</div></div>';
