      S.rows = data.slice(hi + 1).filter(r => r.some(c => String(c).trim())).map(r => { let n = String(r[ci.n]).replace(/\D/g, ''); if (n.length >= 6 && n.length < 10) n = n.padStart(10, '0'); return { nisn: n, nama: String(r[ci.a]).trim(), kelas: String(r[ci.k]).trim() }; });
